def pause_menu():
    global MUTE
    stop_bg_music()
    sel = 1
    total_opts = 3

    while True:
        os.system('cls' if os.name == 'nt' else 'clear')
        pad = "░░░░░░░░░░░░░"
        print(f"\n{pad}\033[48;5;238m\033[38;5;15m{C_BOLD}       GAME PAUSED         {C_RESET}")
        print(f"{pad}___________________________")

        options = [
            "[ESC] Resume",
            f"[M]   Toggle Mute: {1 if MUTE else 0}",
            "[Q]   Quit Game"
        ]

        for i, opt in enumerate(options, 1):
            text_color = C_BOLD + C_WHITE if i == sel else C_WHITE
            print(f"{pad} {text_color}{opt}{C_RESET}")

        print(f"{pad}___________________________")

        while True:
            key = get_key_pressed()
            if key is not None:
                break
            time.sleep(0.05)

        if key in ("arrow_H", "w", "arrow_up", "arrow_A", "a_up"):
            sel = sel - 1 if sel > 1 else total_opts
        elif key in ("arrow_P", "s", "arrow_down", "arrow_B", "a_down"):
            sel = sel + 1 if sel < total_opts else 1
        elif key in ("m", "109"):
            MUTE = not MUTE
        elif key in ("q", "113"):
            return "quit"
        elif key in ("\r", " ", "\n"):
            if sel == 1:
                start_bg_music()
                return "resume"
            elif sel == 2:
                MUTE = not MUTE
            elif sel == 3:
                return "quit"
        elif key == "\x1b":
            start_bg_music()
            return "resume"

def run_game():
    global score, gems, lives, special, bullets_left, level, damage, char_down, difficulty
    score = 0
    gems = 0
    lives = 3
    special = 0
    bullets_left = 10
    level = 1
    damage = 0

    cols = 13 if difficulty == 1 else (11 if difficulty == 2 else (9 if difficulty == 3 else 7))
    view_height = 14

    map_rows = [[" " for _ in range(cols)] for _ in range(view_height)]

    player_col = cols // 2
    player_row = 2

    # Playable, smooth speed settings (starting delays)
    speed_delays = {1: 0.150, 2: 0.080, 3: 0.040, 4: 0.020}
    current_delay = speed_delays[difficulty]

    player_bullets = []
    enemy_bullets = []

    level_goal_row = 150
    level_scroll_count = 0

    start_bg_music()

    tick_count = 0
    flash_item_bg = None
    flash_tick = 0

    while True:
        tick_count += 1
        level_scroll_count += 1

        # Dynamic speed scaling
        if tick_count % 200 == 0:
            min_delay = 0.050 if difficulty == 1 else (0.025 if difficulty == 2 else (0.012 if difficulty == 3 else 0.005))
            if current_delay > min_delay:
                current_delay = max(min_delay, current_delay - 0.005)

        key = get_key_pressed()
        fired = False

        if key is not None:
            if key in ("arrow_K", "a", "arrow_left", "arrow_D", "a_left"):
                if player_col > 0:
                    player_col -= 1
            elif key in ("arrow_M", "d", "arrow_right", "arrow_C", "a_right"):
                if player_col < cols - 1:
                    player_col += 1
            elif key in (" ", "\r", "\n"): # Fire weapon (downwards in levels)
                if gmode == 1:
                    fired = True
                else:
                    if special > 0:
                        special -= 1
                        play_sound_file("cache/boom.wav")
                        for r in range(view_height):
                            for c in range(cols):
                                if map_rows[r][c] not in (" ", char_gem, char_heart, char_sun):
                                    map_rows[r][c] = "."
            elif key == "\x1b":
                act = pause_menu()
                if act == "quit":
                    stop_bg_music()
                    return

        # Firing weapon action
        if fired and gmode == 1:
            if bullets_left > 0:
                bullets_left -= 1
                player_bullets.append([player_col, player_row + 1]) # fires down, +y relative
                play_sound_file("cache/damage.wav")
            elif special > 0:
                special -= 1
                bullets_left = 9
                player_bullets.append([player_col, player_row + 1]) # fires down, +y relative
                play_sound_file("cache/boom.wav")

        # Scroll the map (Move view downwards)
        map_rows.pop(0)
        new_row = [" " for _ in range(cols)]

        if gmode == 1:
            if level_scroll_count == level_goal_row:
                for c in range(cols):
                    new_row[c] = "═"
                new_row[cols // 2] = " "
            elif level_scroll_count > level_goal_row - 10 and level_scroll_count <= level_goal_row + 5:
                pass
            else:
                for c in range(cols):
                    num = random.randint(0, 999)
                    if num < 5:
                        new_row[c] = char_sun
                    elif num >= 100 and num <= 108:
                        new_row[c] = char_heart
                    elif num >= 200 and num <= 215:
                        new_row[c] = char_gem
                    elif num >= 50 and num <= 60 + difficulty * 10:
                        new_row[c] = random.choice(["░", "@", "#", "▒", "▓", "█", "▄", "▀", "▌", "▐"])
        else:
            for c in range(cols):
                num = random.randint(0, 999)
                if num < 5:
                    new_row[c] = char_sun
                elif num >= 100 and num <= 108:
                    new_row[c] = char_heart
                elif num >= 200 and num <= 215:
                    new_row[c] = char_gem
                elif num >= 50 and num <= 60 + difficulty * 10:
                    new_row[c] = random.choice(["░", "@", "#", "▒", "▓", "█", "▄", "▀", "▌", "▐"])

        map_rows.append(new_row)
        score += 1

        # Check level completion
        if gmode == 1 and level_scroll_count >= level_goal_row:
            if player_row == view_height - 1 or level_scroll_count == level_goal_row + 4:
                if player_col == cols // 2:
                    play_sound_file("cache/heart.wav")
                    os.system('cls' if os.name == 'nt' else 'clear')
                    draw_header_title()
                    bonus_pts = level * 500
                    score += bonus_pts
                    print(f"\n{C_BOLD}{C_GREEN}====================================={C_RESET}")
                    print(f"{C_BOLD}{C_GREEN}         LEVEL {level} COMPLETE!{C_RESET}")
                    print(f"{C_BOLD}{C_GREEN}====================================={C_RESET}\n")
                    print(f"  Landing Bonus: +{bonus_pts} pts")
                    print(f"  Current Score: {score}")
                    print(f"\nPress any key for Level {level + 1}...")
                    while True:
                        if get_key_pressed() is not None:
                            break
                        time.sleep(0.05)
                    level += 1
                    level_scroll_count = 0
                    map_rows = [[" " for _ in range(cols)] for _ in range(view_height)]
                    player_bullets = []
                    enemy_bullets = []
                    bullets_left = 10
                    continue
                else:
                    lives -= 1
                    damage += 1
                    play_sound_file("cache/damage.wav")
                    level_scroll_count = level_goal_row - 15

        # Update Player Bullets (moving down screen, +y relative)
        active_bullets = []
        for b in player_bullets:
            bc, br = b
            hit = False
            for step in range(3):
                test_r = br + step
                if test_r < view_height:
                    cell = map_rows[test_r][bc]
                    if cell != " " and cell != "▲":
                        hit = True
                        map_rows[test_r][bc] = " "
                        if cell == char_gem:
                            gems += 1
                            score += 5 * difficulty + 5
                            play_sound_file("cache/gem.wav")
                            flash_item_bg = C_GREEN
                            flash_tick = 3
                        elif cell == char_heart:
                            if lives < 10:
                                lives += 1
                            play_sound_file("cache/heart.wav")
                            flash_item_bg = C_RED
                            flash_tick = 3
                        elif cell == char_sun:
                            special = min(5, special + 1)
                            play_sound_file("cache/boom.wav")
                            flash_item_bg = C_CYAN
                            flash_tick = 3
                        else:
                            map_rows[test_r][bc] = "."
                            play_sound_file("cache/damage.wav")
                        break
                    elif cell == "▲":
                        hit = True
                        map_rows[test_r][bc] = " "
                        score += 1000
                        play_sound_file("cache/boom.wav")
                        break
            if not hit:
                new_br = br + 3
                if new_br < view_height:
                    active_bullets.append([bc, new_br])
        player_bullets = active_bullets

        # Update Enemy Bullets (moving up screen, -y relative)
        active_ebullets = []
        for eb in enemy_bullets:
            ebc, ebr = eb
            hit = False
            for step in range(2):
                test_r = ebr - step
                if test_r >= 0:
                    if test_r == player_row and ebc == player_col:
                        hit = True
                        lives -= 1
                        damage += 1
                        play_sound_file("cache/damage.wav")
                        break
            if not hit:
                new_ebr = ebr - 2
                if new_ebr >= 0:
                    active_ebullets.append([ebc, new_ebr])
        enemy_bullets = active_ebullets

        # Update Enemies on map (scrolling up naturally, moving side-to-side every 2 ticks towards player_col)
        if gmode == 1:
            acc_thresholds = {1: 30, 2: 50, 3: 70, 4: 90}
            thresh = acc_thresholds[difficulty]

            enemies = []
            for r in range(view_height):
                for c in range(cols):
                    if map_rows[r][c] == "▲":
                        map_rows[r][c] = " "
                        enemies.append((c, r))

            for c, r in enemies:
                new_c = c
                if tick_count % 2 == 0:
                    if random.randint(0, 99) < thresh:
                        if c < player_col:
                            new_c = min(cols - 1, c + 1)
                        elif c > player_col:
                            new_c = max(0, c - 1)
                    else:
                        move = random.choice([-1, 0, 1])
                        new_c = max(0, min(cols - 1, c + move))
                if random.randint(0, 5) == 0:
                    enemy_bullets.append([new_c, r - 1])
                map_rows[r][new_c] = "▲"

            if tick_count % 15 == 0:
                spawn_c = random.randint(0, cols - 1)
                if map_rows[view_height - 1][spawn_c] == " ":
                    map_rows[view_height - 1][spawn_c] = "▲"

        # Resolve player direct collisions
        player_cell = map_rows[player_row][player_col]
        if player_cell != " ":
            map_rows[player_row][player_col] = " "
            if player_cell == char_gem:
                gems += 1
                score += 5 * difficulty + 5
                play_sound_file("cache/gem.wav")
            elif player_cell == char_heart:
                if lives < 10:
                    lives += 1
                play_sound_file("cache/heart.wav")
            elif player_cell == char_sun:
                special = min(5, special + 1)
                play_sound_file("cache/boom.wav")
            elif player_cell in ("▲", "•", "↑"):
                lives -= 1
                damage += 1
                play_sound_file("cache/damage.wav")
            else:
                damage += 1
                play_sound_file("cache/damage.wav")
                if special > 0:
                    special -= 1
                    lives -= 1
                else:
                    lives -= 3

        if lives <= 0:
            stop_bg_music()
            game_over_screen()
            return

        # RENDER FRAME
        frame_buffer = []
        pad_size = 5
        sidebar = " " * pad_size

        # Top Bar
        hearts_str = f"{C_RED}{char_heart * lives}{C_RESET}" + f"{C_WHITE}_{C_RESET}" * (10 - lives)
        shield_str = f"{C_CYAN}{char_sun * special}{C_RESET}" + f"{C_WHITE}_{C_RESET}" * (5 - special)
        frame_buffer.append(f"\n{sidebar}{C_BOLD}{C_WHITE} Lives: {hearts_str}  Shields: {shield_str}{C_RESET}\n")

        # Draw map
        for r in range(view_height):
            line_parts = []
            for c in range(cols):
                is_bullet = False
                for b in player_bullets:
                    if b[0] == c and b[1] == r:
                        is_bullet = True
                        break
                is_ebullet = False
                for eb in enemy_bullets:
                    if eb[0] == c and eb[1] == r:
                        is_ebullet = True
                        break

                if r == player_row and c == player_col:
                    if flash_tick > 0 and flash_item_bg:
                        line_parts.append(f"{flash_item_bg}{char_down}{C_RESET}")
                    else:
                        line_parts.append(f"{C_CYAN}{C_BOLD}{char_down}{C_RESET}")
                elif is_bullet:
                    line_parts.append(f"{C_YELLOW}•{C_RESET}")
                elif is_ebullet:
                    line_parts.append(f"{C_RED}↑{C_RESET}")
                else:
                    cell = map_rows[r][c]
                    if cell == "▲":
                        line_parts.append(f"{C_RED}▲{C_RESET}")
                    elif cell == char_gem:
                        line_parts.append(f"{C_GREEN}{char_gem}{C_RESET}")
                    elif cell == char_heart:
                        line_parts.append(f"{C_RED}{char_heart}{C_RESET}")
                    elif cell == char_sun:
                        line_parts.append(f"{C_CYAN}{char_sun}{C_RESET}")
                    elif cell in ("░", "▒", "▓", "█"):
                        line_parts.append(f"{C_WHITE}{cell}{C_RESET}")
                    else:
                        line_parts.append(cell)

            middle_map = "".join(line_parts)
            frame_buffer.append(f"{sidebar}{C_WHITE}│{C_RESET}{middle_map}{C_WHITE}│{C_RESET}\n")

        # Bottom Bar
        ammo_str = f" [Ammo: {bullets_left}]" if gmode == 1 else ""
        gmode_str = "Levels" if gmode == 1 else "Endless"
        frame_buffer.append(f"{sidebar}{C_BOLD}{C_GREEN}Score: {score}  Level: {level} ({gmode_str}){ammo_str}{C_RESET}\n")

        sys.stdout.write("\033[H" + "".join(frame_buffer))
        sys.stdout.flush()

        if flash_tick > 0:
            flash_tick -= 1

        time.sleep(current_delay)

def game_over_screen():
    global score, gems, level, difficulty, damage
    os.system('cls' if os.name == 'nt' else 'clear')
    draw_header_title()
    print(f"\n{C_BOLD}{C_RED}====================================={C_RESET}")
    print(f"{C_BOLD}{C_RED}             GAME OVER{C_RESET}")
    print(f"{C_BOLD}{C_RED}====================================={C_RESET}\n")
    print(f"  Score      : {score}")
    print(f"  Level      : {level}")
    print(f"  Gems       : {gems}")
    print(f"  Damage Taken: {damage}")

    bonus = level * 10 * difficulty
    final_score = score + bonus

    print(f"  Level Bonus: +{bonus}")
    print(f"  ------------------------")
    print(f"  {C_BOLD}{C_GREEN}FINAL SCORE: {final_score}{C_RESET}")
    print()

    print("Enter your initials (3 Letters): ", end="")
    sys.stdout.flush()

    initials = ""
    while len(initials) < 3:
        key = get_key_pressed()
        if key is not None and len(key) == 1 and key.isalpha():
            initials += key.upper()
            sys.stdout.write(key.upper())
            sys.stdout.flush()
        time.sleep(0.05)

    save_local_score(initials, final_score, score, bonus, level, difficulty, gems, damage)
    print("\n\nScore Saved Locally!")
    print("Press any key to return to main menu...")
    while True:
        if get_key_pressed() is not None:
            break
        time.sleep(0.05)

if __name__ == "__main__":
    os.makedirs("cache", exist_ok=True)
    os.makedirs("data", exist_ok=True)

    # Reconstruct embedded files if missing
    try:
        if "EMBEDDED_ASSETS" in globals():
            for name, b64_data in EMBEDDED_ASSETS.items():
                filepath = os.path.join("cache", name)
                if not os.path.exists(filepath):
                    with open(filepath, "wb") as f:
                        f.write(base64.b64decode(b64_data))
    except Exception:
        pass

    # Hide cursor
    if os.name == 'nt':
        class _CursorInfo(ctypes.Structure):
            _fields_ = [("dwSize", ctypes.c_int), ("bVisible", ctypes.c_byte)]
        ci = _CursorInfo()
        handle = kernel32.GetStdHandle(-11)
        kernel32.GetConsoleCursorInfo(handle, ctypes.byref(ci))
        ci.bVisible = False
        kernel32.SetConsoleCursorInfo(handle, ctypes.byref(ci))
    else:
        sys.stdout.write("\033[?25l")
        sys.stdout.flush()

    try:
        main_menu()
    finally:
        # Show cursor on exit
        if os.name == 'nt':
            ci.bVisible = True
            kernel32.SetConsoleCursorInfo(handle, ctypes.byref(ci))
        else:
            sys.stdout.write("\033[?25h")
            sys.stdout.flush()
